#!/usr/bin/env bash
# Profile CI's matrix (ADR-0003): every profile in the catalog, each generated by the CLI from the real packs alone,
# so a new profile is run without editing the workflow. Needs a Release build of the CLI.
#
# Writes one line for $GITHUB_OUTPUT, profiles=["...", ...]. A profile whose packs are not all written gets an
# ::error:: naming the packs it lacks (the slots only those packs declare fail too, and are not repeated), and the
# script fails once every profile has been tried, without writing the line. A profile that fails to generate with
# every pack present fails it at once.
# Usage: build/complete-profiles.sh >> "$GITHUB_OUTPUT"
set -euo pipefail

repository="$(cd "$(dirname "$0")/.." && pwd)"
cli="$repository/src/Fabric.Cli/bin/Release/net10.0/fabric.dll"
work="$(mktemp -d)"
trap 'rm -rf "$work"' EXIT

fabric() { dotnet "$cli" "$@"; }

missing_prefix="error: no pack for "
# Assigned first: a failing command substitution inside the for list would not stop the script.
profiles="$(fabric profiles)"
complete=()
incomplete=0
for profile in $profiles; do
  if errors="$(fabric new "$work/$profile" --name shop --profile "$profile" 2>&1 >/dev/null)"; then
    complete+=("\"$profile\"")
  elif grep --quiet "^$missing_prefix" <<<"$errors"; then
    missing="$(grep "^$missing_prefix" <<<"$errors" | sed -e "s/^$missing_prefix//" -e 's/\.$//' | paste -s -d , - | sed 's/,/, /g')"
    echo "::error title=profile CI::$profile is not complete, its packs are not all written: no pack for $missing." >&2
    incomplete=$((incomplete + 1))
  else
    echo "::error title=profile CI::$profile does not generate:" >&2
    echo "$errors" >&2
    exit 1
  fi
done

[ "$incomplete" -eq 0 ] || exit 1
echo "profiles=[$(IFS=,; echo "${complete[*]}")]"
